        if (!ENABLED || phase == Phase.DONE) return;

        if (!announced) {
            announced = true;
            Constants.LOG.info("RenderScale autotest enabled");
        }

        totalTicks++;
        phaseTicks++;

        try {
            step(client);

            if (totalTicks > WATCHDOG_TICKS) {
                throw new AssertionError("Autotest timed out in phase " + phase);
